input.content:
// TEMPORARY, NOT FOR COMMIT. Reproductions for the survey of buttons that
// show the wrong state (2026-11-20). Chosen by JUSPRIN_REPRO, pictures to
// JUSPRIN_REPRO_DIR. Each prints "REPRO ..." lines: what the app holds
// beside what the page draws.

std::chrono::steady_clock::time_point m_repro_start{};

static std::string repro_kind()
{
    const char* kind = std::getenv("JUSPRIN_REPRO");
    return kind != nullptr ? kind : "";
}

void repro_begin()
{
    if (const char* dir = std::getenv("JUSPRIN_REPRO_DIR"))
        m_state->capture_dir = fs::absolute(dir);
    m_repro_start = std::chrono::steady_clock::now();
}

double repro_seconds() const
{
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - m_repro_start).count();
}

// --- 1. A value the app owns, copied onto the chat page ----------------

std::string repro_new_chat_button()
{
    return run_in_chat("(() => { const b = document.querySelector('button[aria-label=\"New chat\"]');"
                       " return b ? (b.disabled ? 'GREYED' : 'enabled') : 'missing'; })()");
}

bool repro_app_busy()
{
    auto& host = installed_shell()->agent_pane()->web_view().host();
    return host.busy() || std::any_of(host.tools().activities().begin(), host.tools().activities().end(),
                                      [](const Agent::ToolActivity& activity) { return !Agent::tool_state_terminal(activity.state); });
}

void repro_chat_log(const std::string& label)
{
    std::cout << "REPRO chat t=" << std::fixed << std::setprecision(1) << repro_seconds() << "s " << label
              << ": app_busy=" << (repro_app_busy() ? "YES" : "no") << " new_chat_button=" << repro_new_chat_button()
              << " chats=" << persistence().document().conversations().size() << std::endl;
    capture_web_view(installed_shell()->agent_pane()->web_view().webview(), "chat-" + label);
}

void repro_press_new_chat()
{
    run_in_chat("(() => { const b = document.querySelector('button[aria-label=\"New chat\"]'); if (b) b.click(); })()");
}

void repro_chat_busy()
{
    repro_begin();
    double x = 100, y = 100, z = 60;
    if (const char* box = std::getenv("JUSPRIN_REPRO_BOX"))
        std::sscanf(box, "%lf,%lf,%lf", &x, &y, &z);
    const std::string source = (fs::path(data_dir()) / "repro-box.stl").string();
    {
        std::ofstream out(source);
        out << "solid box\n";
        write_box(out, {-x / 2, -y / 2, 0}, {x / 2, y / 2, z});
        out << "endsolid box\n";
    }
    const bool loaded = m_plater->load_files(std::vector<boost::filesystem::path>{source},
                                             LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false)
                            .size() == 1;
    check(loaded, "repro_model_loaded");
    if (!loaded) {
        finish();
        return;
    }
    wait_until([this] { return repro_new_chat_button() != "missing"; }, "repro_chat_page_ready",
               [self = shared_from_this()] { self->after(1500, "repro_page_settled", [self] { self->repro_chat_busy_run(); }); });
}

void repro_chat_busy_run()
{
    m_repro_start = std::chrono::steady_clock::now();
    repro_chat_log("1-before-anything");
    auto&      host     = installed_shell()->agent_pane()->web_view().host();
    const auto snapshot = installed_shell()->workspace()->snapshot();
    // A slice no reply is waiting on, as an outside program's is.
    host.tools().submit({"slice_start", nlohmann::json{{"plateId", std::to_string(snapshot.plates.at(0).id.value())}}.dump()},
                        "repro-busy");
    auto self = shared_from_this();
    after(1500, "repro_a", [self] {
        self->repro_chat_log("2-slice-running-nothing-pressed");
        self->repro_press_new_chat();
        self->after(700, "repro_b", [self] {
            self->repro_chat_log("3-after-pressing-new-chat");
            const std::string id = self->persistence().document().active_conversation_id();
            self->run_in_chat("window.__jusprinTest.renameConversation(" + nlohmann::json(id).dump() + ", 'Renamed while slicing')");
            self->after(700, "repro_c", [self] {
                self->repro_chat_log("4-after-renaming-the-chat");
                self->repro_press_new_chat();
                self->after(700, "repro_d", [self] {
                    self->repro_chat_log("5-after-pressing-new-chat-again");
                    self->wait_until([self] { return !self->repro_app_busy(); }, "repro_slice_ends", [self] {
                        self->repro_chat_log("6-slice-just-ended");
                        self->after(5000, "repro_e", [self] {
                            self->repro_chat_log("7-five-seconds-after-the-slice-ended");
                            self->after(32000, "repro_f", [self] {
                                self->repro_chat_log("8-37-seconds-after-the-slice-ended");
                                self->finish();
                            });
                        });
                    });
                });
            });
        });
    });
}

// --- shared by the modal windows --------------------------------------

// Every button on the page with its greyed state, and which screen it is,
// left in the page's title for the next tick to read.
static const char* repro_read_script()
{
    return "(function () {"
           " var screen = Array.prototype.map.call(document.querySelectorAll('[data-testid^=setup-local-]'),"
           "   function (e) { return e.getAttribute('data-testid'); }).join(',');"
           " var buttons = Array.prototype.map.call(document.querySelectorAll('button:not(.prefs-nav-item)'), function (b) {"
           "   return (b.innerText || b.getAttribute('aria-label') || '?').replace(/\\s+/g, ' ').trim() + (b.disabled ? ' [GREYED]' : ''); });"
           " var words = Array.prototype.map.call(document.querySelectorAll('h1, .pane-state > p, [role=alert], .orca-import-lead'),"
           "   function (e) { return e.innerText.replace(/\\s+/g, ' ').trim(); }).join(' / ');"
           " var refused = (window.__reproRefused || []).join(';');"
           " document.title = 'repro:screen=' + screen + ' words=' + words.slice(0, 160) + ' buttons=' + buttons.join(' | ') +"
           "   ' app_refusals_the_page_received=' + refused; })()";
}

// Records, without changing them, the refusals the app sends this page.
static const char* repro_watch_refusals_script()
{
    return "(function () { if (window.__reproRefused || !window.__jusprinBridge) return; window.__reproRefused = [];"
           " var real = window.__jusprinBridge.deliver;"
           " window.__jusprinBridge.deliver = function (envelope) {"
           "   try { var e = typeof envelope === 'string' ? JSON.parse(envelope) : envelope;"
           "     if (e && e.type === 'bridge_error') window.__reproRefused.push(e.payload.code + ':' + e.payload.message); } catch (x) {}"
           "   return real(envelope); }; })()";
}

static std::string repro_title(wxWebView* page)
{
    const std::string title = ui_text(page->GetCurrentTitle());
    return title.rfind("repro:", 0) == 0 ? title.substr(6) : "(not read yet)";
}

// --- 2. A wait the app never answers, with no failure -------------------

void repro_import_cancelled()
{
    using namespace std::chrono_literals;
    repro_begin();
    const fs::path orca = fs::path(data_dir()) / "repro-orca";
    fs::create_directories(orca);
    {
        std::ofstream conf((orca / "OrcaSlicer.conf").string());
        conf << R"({"models": [{"vendor": "BBL", "model": "Bambu Lab A1 mini", "nozzle_diameter": "0.4"},)"
             << R"({"vendor": "Creality", "model": "Creality K1C", "nozzle_diameter": "0.4"},)"
             << R"({"vendor": "BBL", "model": "Bambu Lab P1S", "nozzle_diameter": "0.4"}]})"
             << "\n# MD5 checksum 0123\n";
    }
    setenv("JUSPRIN_ORCA_DATADIR", orca.string().c_str(), 1);
    // A change to the project's settings that is not saved.
    DynamicPrintConfig changed;
    changed.set_deserialize_strict("sparse_infill_density", "5%");
    wxGetApp().get_tab(Preset::TYPE_PRINT)->load_config(changed);
    std::cout << "REPRO import: project has unsaved setting changes=" << wxGetApp().has_current_preset_changes() << std::endl;

    struct Run
    {
        int                                   step{0};
        std::chrono::steady_clock::time_point at{};
        std::chrono::steady_clock::time_point pressed{};
        bool                                  done{false};
        bool                                  pictured_late{false};
    };
    auto run     = std::make_shared<Run>();
    m_modal_gate = [this, run](wxDialog& dialog) {
        auto* window = dynamic_cast<Slic3r::GUI::JusPrin::Home::OrcaImportWindow*>(&dialog);
        if (window == nullptr) {
            std::cout << "REPRO import t=" << std::fixed << std::setprecision(1) << repro_seconds() << "s: the person presses Cancel on '"
                      << ui_text(dialog.GetTitle()) << "'" << std::endl;
            return true;
        }
        if (run->done)
            return true;
        wxWebView* page = nullptr;
        for (wxWindow* child : window->GetChildren())
            if (auto* view = dynamic_cast<Slic3r::GUI::JusPrin::AgentWebView*>(child))
                page = view->webview();
        if (page == nullptr)
            return false;
        const auto now = std::chrono::steady_clock::now();
        if (run->at == std::chrono::steady_clock::time_point{})
            run->at = now;
        if (now < run->at + 1s)
            return false;
        run->at = now;
        const std::string seen = repro_title(page);
        WebView::RunScript(page, repro_read_script());
        switch (run->step) {
        case 0:
            if (seen.find("Import ") == std::string::npos || seen.find("Importing") != std::string::npos) {
                std::cout << "REPRO import: waiting for the list: " << seen << std::endl;
                return false;
            }
            std::cout << "REPRO import: window as it opens: " << seen << std::endl;
            capture_web_view(page, "import-1-as-it-opens");
            WebView::RunScript(page, "(function () { var b = document.querySelector('button.primary'); if (b && !b.disabled) b.click(); })()");
            std::cout << "REPRO import: the person presses the Import button" << std::endl;
            run->pressed = now;
            ++run->step;
            return false;
        default: {
            const double since = std::chrono::duration<double>(now - run->pressed).count();
            std::cout << "REPRO import " << std::fixed << std::setprecision(0) << since << "s after pressing Import: " << seen << std::endl;
            if (run->step == 6)
                capture_web_view(page, "import-2-after-cancelling-the-question");
            if (since > 45) {
                capture_web_view(page, "import-3-45-seconds-later");
                run->done = true;
            }
            ++run->step;
            return false;
        }
        }
    };
    m_modals_before = m_modals_answered;
    answer_modals(wxID_CANCEL);
    installed_shell()->open_orca_import();
    stop_answering_modals();
    finish();
}

// --- 3 and 4. Preferences › BYOAI, connecting an outside AI tool --------

// 3: the folder holding Cursor's settings file cannot be written.
// 4: a setup command still running when the person presses Connect again.
void repro_connect_tool(bool read_only_folder)
{
    using namespace std::chrono_literals;
    repro_begin();
    const char* home_env = std::getenv("HOME");
    const std::string home = home_env != nullptr ? home_env : "";
    if (home.find("scratchpad") == std::string::npos) {
        fail("the repro runs only with HOME in the scratchpad, never the person's own");
        return;
    }
    const fs::path cursor = fs::path(home) / ".cursor";
    if (read_only_folder) {
        fs::create_directories(cursor);
        {
            std::ofstream file((cursor / "mcp.json").string());
            file << "{}\n";
        }
        fs::permissions(cursor, fs::perms::owner_read | fs::perms::owner_exe);
    } else {
        const fs::path bin = fs::path(data_dir()) / "stand-in-bin";
        fs::create_directories(bin);
        {
            boost::nowide::ofstream script((bin / "claude").string());
            script << "#!/bin/sh\nsleep 25\nexit 0\n";
        }
        fs::permissions(bin / "claude", fs::perms::owner_all);
        wxString path;
        wxGetEnv("PATH", &path);
        wxSetEnv("PATH", wxString::FromUTF8(bin.string()) + ":" + path);
    }
    const std::string tool = read_only_folder ? "cursor" : "claude";
    const std::string name = read_only_folder ? "settings" : "refused";
    const int reported_before = unexpected_errors_logged();

    struct Run
    {
        int                                   step{0};
        std::chrono::steady_clock::time_point at{};
        std::chrono::steady_clock::time_point pressed{};
        bool                                  done{false};
        bool                                  left{false};
    };
    auto run     = std::make_shared<Run>();
    m_modal_gate = [this, run, tool, name, read_only_folder](wxDialog& dialog) {
        auto* window = dynamic_cast<Preferences::PreferencesWindow*>(&dialog);
        if (window == nullptr) {
            std::cout << "REPRO " << name << " t=" << std::fixed << std::setprecision(1) << repro_seconds()
                      << "s: another window opened and the person closes it: '" << ui_text(dialog.GetTitle()) << "'" << std::endl;
            return true;
        }
        if (run->done)
            return true;
        if (!window->page_connected())
            return false;
        wxWebView* page = window->web_view().webview();
        const auto now  = std::chrono::steady_clock::now();
        if (run->at == std::chrono::steady_clock::time_point{})
            run->at = now;
        if (now < run->at + 1s)
            return false;
        run->at = now;
        const std::string seen  = repro_title(page);
        const double      since = std::chrono::duration<double>(now - run->pressed).count();
        const std::string open_tool = "(function () { var b = document.querySelector('[data-testid=agent-tool-" + tool +
                                      "] .agent-row-action'); if (b) b.click(); })()";
        const std::string press_connect =
            "(function () { var b = document.querySelector('[data-testid^=setup-local-] .setup-actions .primary');"
            " if (b && !b.disabled) b.click(); })()";
        WebView::RunScript(page, repro_watch_refusals_script());
        switch (run->step) {
        case 0:
            WebView::RunScript(page, "document.querySelectorAll('.prefs-nav-item')[1].click()");
            ++run->step;
            return false;
        case 1:
            WebView::RunScript(page, open_tool);
            ++run->step;
            return false;
        case 2:
            WebView::RunScript(page, repro_read_script());
            ++run->step;
            return false;
        case 3:
            WebView::RunScript(page, repro_read_script());
            if (seen.find("Connect") == std::string::npos || seen.find("Connect [GREYED]") != std::string::npos ||
                seen.find("Connect… [GREYED]") != std::string::npos) {
                std::cout << "REPRO " << name << ": waiting for Connect: " << seen << std::endl;
                return false;
            }
            std::cout << "REPRO " << name << ": before pressing Connect: " << seen << std::endl;
            capture_web_view(page, name + "-1-before-pressing-connect");
            WebView::RunScript(page, press_connect);
            std::cout << "REPRO " << name << ": the person presses Connect" << std::endl;
            run->pressed = now;
            ++run->step;
            return false;
        default:
            break;
        }
        WebView::RunScript(page, repro_read_script());
        std::cout << "REPRO " << name << " " << std::fixed << std::setprecision(0) << since << "s after pressing Connect: " << seen
                  << std::endl;
        if (read_only_folder) {
            // 3: watch the wait, then leave the section and come back.
            if (run->step == 8)
                capture_web_view(page, name + "-2-a-few-seconds-after");
            if (since > 45 && !run->left) {
                capture_web_view(page, name + "-3-45-seconds-after");
                WebView::RunScript(page, "document.querySelectorAll('.prefs-nav-item')[2].click()");
                std::cout << "REPRO " << name << ": the person opens another section" << std::endl;
                run->left = true;
            } else if (since > 49) {
                capture_web_view(page, name + "-4-after-opening-another-section");
                run->done = true;
            }
        } else {
            // 4: leave while the command runs, come back, press Connect again.
            if (run->step == 5) {
                capture_web_view(page, name + "-2-command-running");
                WebView::RunScript(page, "document.querySelectorAll('.prefs-nav-item')[2].click()");
                std::cout << "REPRO " << name << ": the person opens another section" << std::endl;
            } else if (run->step == 6) {
                WebView::RunScript(page, "document.querySelectorAll('.prefs-nav-item')[1].click()");
                std::cout << "REPRO " << name << ": the person comes back to BYOAI" << std::endl;
            } else if (run->step == 7) {
                WebView::RunScript(page, open_tool);
                std::cout << "REPRO " << name << ": the person opens the tool again" << std::endl;
            } else if (run->step == 9) {
                capture_web_view(page, name + "-3-back-on-the-tool");
                WebView::RunScript(page, press_connect);
                std::cout << "REPRO " << name << ": the person presses Connect a second time" << std::endl;
            } else if (run->step == 11) {
                capture_web_view(page, name + "-4-after-the-second-press");
            } else if (since > 40) {
                capture_web_view(page, name + "-5-40-seconds-after");
                run->done = true;
            }
        }
        ++run->step;
        return false;
    };
    m_modals_before = m_modals_answered;
    answer_modals(wxID_CANCEL);
    installed_shell()->request_preferences();
    wait_until([this] { return preferences_closed(); }, "repro_preferences_closed",
               [self = shared_from_this(), cursor, read_only_folder, reported_before, name] {
                   self->stop_answering_modals();
                   if (read_only_folder)
                       fs::permissions(cursor, fs::perms::owner_all);
                   std::cout << "REPRO " << name << ": unexpected errors the app reported during the run="
                             << unexpected_errors_logged() - reported_before << std::endl;
                   self->finish();
               });
}

